{
  "findings": [
    {
      "check_id": "CKV_AWS_79",
      "title": "Instance Metadata Service v1 is enabled",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not require IMDSv2, allowing instances to use the less secure IMDSv1 protocol and increasing the risk of credential theft through SSRF vulnerabilities."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "Root EBS volume encryption is not enforced",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not explicitly encrypt its root EBS volume, so data at rest may be unencrypted depending on the selected AMI and account defaults."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"levelup-launchconfig\" {\n  name_prefix   = \"levelup-launchconfig\"\n  image_id      = lookup(var.AMIS, var.AWS_REGION)\n  instance_type = \"t2.micro\"\n  key_name      = aws_key_pair.levelup_key.key_name\n\n  metadata_options {\n    http_tokens = \"required\"\n  }\n\n  root_block_device {\n    encrypted = true\n  }\n}\n",
  "fix_summary": "Required IMDSv2 for launched instances and enabled encryption for the root EBS volume."
}
